-- [ARCHIVED MIGRATION]: sql/archive/18_teacher_activity_homework_fix.sql
-- ==============================================================================
-- =============================================================
-- مدارس أمين الرضا (ع) — إصلاح تثبيت الحصص والواجبات للمعلمات
-- يعتمد على class_sessions / homeworks / teacher_activity_log من SQL 08
-- =============================================================

create extension if not exists pgcrypto;

-- تأكد من وجود الأعمدة والجداول الأساسية
create table if not exists public.teacher_activity_log (
  id uuid primary key default gen_random_uuid(),
  class_session_id uuid null references public.class_sessions(id) on delete cascade,
  teacher_id uuid not null references public.users(id),
  activity_type text not null,
  evidence_table text,
  evidence_id uuid,
  activity_weight numeric not null default 1,
  notes text,
  occurred_at timestamptz not null default now(),
  created_by uuid null references public.users(id)
);

create table if not exists public.homeworks (
  id uuid primary key default gen_random_uuid(),
  class_session_id uuid null references public.class_sessions(id) on delete set null,
  academic_period_id uuid null references public.academic_periods(id) on delete set null,
  class_id uuid null references public.classes(id),
  subject_id uuid null references public.subjects(id),
  teacher_id uuid null references public.users(id),
  title text not null,
  description text,
  assigned_date date not null default current_date,
  due_date date,
  status text not null default 'published',
  created_at timestamptz not null default now()
);

-- فهرس يمنع تكرار تثبيت نفس الحصة بنفس نوع النشاط من دون evidence.
do $$ begin
  begin
    create unique index if not exists uq_teacher_activity_manual_session
      on public.teacher_activity_log(class_session_id, teacher_id, activity_type)
      where evidence_id is null;
  exception when others then
    raise notice 'تعذر إنشاء unique index لنشاط المعلمة: %', sqlerrm;
  end;
end $$;

-- دالة تثبيت حصة
create or replace function public.confirm_teacher_session(
  p_session_id uuid,
  p_activity_type text default 'manual_confirm',
  p_notes text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  s record;
  actor uuid := auth.uid();
begin
  select * into s
  from public.class_sessions
  where id = p_session_id;

  if s.id is null then
    return jsonb_build_object('ok', false, 'message', 'الحصة غير موجودة');
  end if;

  if s.teacher_id is null then
    return jsonb_build_object('ok', false, 'message', 'لا توجد معلمة مرتبطة بهذه الحصة');
  end if;

  if s.status = 'holiday' then
    return jsonb_build_object('ok', false, 'message', 'لا يمكن تثبيت حصة في يوم عطلة');
  end if;

  insert into public.teacher_activity_log (
    class_session_id,
    teacher_id,
    activity_type,
    activity_weight,
    notes,
    created_by
  ) values (
    p_session_id,
    s.teacher_id,
    coalesce(p_activity_type,'manual_confirm'),
    1,
    coalesce(p_notes,'تثبيت حصة من الواجهة'),
    actor
  ) on conflict do nothing;

  update public.class_sessions
  set status = 'completed', updated_at = now()
  where id = p_session_id;

  return jsonb_build_object('ok', true, 'message', 'تم تثبيت الحصة');
end;
$$;

-- دالة إنشاء واجب مرتبط بحصة وتسجيل نشاط للمعلمة
create or replace function public.create_session_homework(
  p_session_id uuid,
  p_title text,
  p_description text default null,
  p_due_date date default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  s record;
  hw_id uuid;
  actor uuid := auth.uid();
begin
  select * into s
  from public.class_sessions
  where id = p_session_id;

  if s.id is null then
    return jsonb_build_object('ok', false, 'message', 'الحصة غير موجودة');
  end if;

  if s.teacher_id is null then
    return jsonb_build_object('ok', false, 'message', 'لا توجد معلمة مرتبطة بهذه الحصة');
  end if;

  if s.status = 'holiday' then
    return jsonb_build_object('ok', false, 'message', 'لا يمكن إنشاء واجب في يوم عطلة');
  end if;

  insert into public.homeworks (
    class_session_id,
    academic_period_id,
    class_id,
    subject_id,
    teacher_id,
    title,
    description,
    assigned_date,
    due_date,
    status
  ) values (
    p_session_id,
    s.academic_period_id,
    s.class_id,
    s.subject_id,
    s.teacher_id,
    coalesce(nullif(trim(p_title),''),'واجب'),
    p_description,
    s.session_date,
    p_due_date,
    'published'
  ) returning id into hw_id;

  insert into public.teacher_activity_log (
    class_session_id,
    teacher_id,
    activity_type,
    evidence_table,
    evidence_id,
    activity_weight,
    notes,
    created_by
  ) values (
    p_session_id,
    s.teacher_id,
    'homework',
    'homeworks',
    hw_id,
    1,
    'تم تسجيل نشاط بسبب نشر واجب',
    actor
  ) on conflict do nothing;

  update public.class_sessions
  set status = 'completed', updated_at = now()
  where id = p_session_id;

  return jsonb_build_object('ok', true, 'message', 'تم نشر الواجب وتثبيت نشاط المعلمة', 'homework_id', hw_id);
end;
$$;

grant execute on function public.confirm_teacher_session(uuid,text,text) to authenticated;
grant execute on function public.create_session_homework(uuid,text,text,date) to authenticated;
grant select, insert, update on public.teacher_activity_log to authenticated;
grant select, insert, update on public.homeworks to authenticated;

notify pgrst, 'reload schema';



-- ==============================================================================
-- [ARCHIVED MIGRATION]: sql/archive/19_teacher_workflow_policies.sql
-- ==============================================================================
-- =============================================================
-- مدارس أمين الرضا (ع) — صلاحيات لوحة المعلم وسير العمل العملي
-- الحضور الافتراضي: الطالب حاضر ما لم يثبت غيابه أو تأخيره.
-- الغياب: مبرر / غير مبرر.
-- المعلم يرى/يدخل فقط للصفوف والمواد المرتبطة به في weekly_schedule.
-- =============================================================

create extension if not exists pgcrypto;

-- أعمدة الحضور الحصة-بحصة
alter table public.attendance add column if not exists absence_type text check (absence_type in ('excused','unexcused') or absence_type is null);
alter table public.attendance add column if not exists period_number int;
alter table public.attendance add column if not exists subject_id uuid null references public.subjects(id);
alter table public.attendance add column if not exists attendance_type text not null default 'daily';

-- تعديل فهرس الحضور ليقبل الحضور الحصة-بحصة
-- الفهرس القديم إن وجد كان يمنع تعدد الحصص في نفس اليوم.
drop index if exists public.uniq_attendance_student_date_type;
do $$ begin
  begin
    create unique index if not exists uniq_attendance_student_date_period_type
      on public.attendance(student_id, date, coalesce(period_number,0), attendance_type)
      where student_id is not null and date is not null and attendance_type is not null;
  exception when others then
    raise notice 'تعذر إنشاء فهرس الحضور الجديد بسبب تكرارات حالية: %', sqlerrm;
  end;
end $$;

-- دوال مساعدة للصلاحيات
create or replace function public.is_admin_user()
returns boolean
language sql
security definer
set search_path = public
stable
as $$
  select exists(
    select 1 from public.users u
    where u.id = auth.uid()
      and (u.role = 'admin' or coalesce(u.is_super_admin,false) = true)
  );
$$;

create or replace function public.teacher_has_class_subject(p_class_id uuid, p_subject_id uuid)
returns boolean
language sql
security definer
set search_path = public
stable
as $$
  select public.is_admin_user()
    or exists(
      select 1
      from public.weekly_schedule ws
      where ws.teacher_id = auth.uid()
        and ws.class_id = p_class_id
        and (p_subject_id is null or ws.subject_id = p_subject_id)
    );
$$;

create or replace function public.teacher_has_student(p_student_id uuid)
returns boolean
language sql
security definer
set search_path = public
stable
as $$
  select public.is_admin_user()
    or exists(
      select 1
      from public.students s
      join public.weekly_schedule ws on ws.class_id = s.class_id
      where s.id = p_student_id
        and ws.teacher_id = auth.uid()
    );
$$;

grant execute on function public.is_admin_user() to authenticated;
grant execute on function public.teacher_has_class_subject(uuid,uuid) to authenticated;
grant execute on function public.teacher_has_student(uuid) to authenticated;

-- تفعيل RLS للجداول ذات العلاقة
alter table public.attendance enable row level security;
alter table public.continuous_assessments enable row level security;
alter table public.exams enable row level security;
alter table public.exam_scores enable row level security;
alter table public.homeworks enable row level security;
alter table public.class_sessions enable row level security;
alter table public.weekly_schedule enable row level security;
alter table public.students enable row level security;

-- قراءة الطلاب للمعلم حسب جدوله
-- لا ننشئ policy إذا كانت موجودة بنفس الاسم.
do $$ begin
  if not exists(select 1 from pg_policies where schemaname='public' and tablename='students' and policyname='teacher_students_read_by_schedule') then
    create policy teacher_students_read_by_schedule on public.students
      for select to authenticated
      using (public.is_admin_user() or public.teacher_has_student(id) or parent_id = auth.uid() or user_id = auth.uid());
  end if;
end $$;

-- weekly_schedule قراءة للمعلم لجدوله
-- الإدارة تقرأ الكل.
do $$ begin
  if not exists(select 1 from pg_policies where schemaname='public' and tablename='weekly_schedule' and policyname='teacher_schedule_read_own') then
    create policy teacher_schedule_read_own on public.weekly_schedule
      for select to authenticated
      using (public.is_admin_user() or teacher_id = auth.uid());
  end if;
end $$;

-- class_sessions قراءة للمعلم لجلساته
do $$ begin
  if not exists(select 1 from pg_policies where schemaname='public' and tablename='class_sessions' and policyname='teacher_sessions_read_own') then
    create policy teacher_sessions_read_own on public.class_sessions
      for select to authenticated
      using (public.is_admin_user() or teacher_id = auth.uid());
  end if;
end $$;

-- attendance: قراءة/إدخال/تعديل/حذف للمعلم لطلابه فقط
do $$ begin
  if not exists(select 1 from pg_policies where schemaname='public' and tablename='attendance' and policyname='teacher_attendance_read_students') then
    create policy teacher_attendance_read_students on public.attendance
      for select to authenticated
      using (public.is_admin_user() or public.teacher_has_student(student_id));
  end if;
  if not exists(select 1 from pg_policies where schemaname='public' and tablename='attendance' and policyname='teacher_attendance_insert_students') then
    create policy teacher_attendance_insert_students on public.attendance
      for insert to authenticated
      with check (public.is_admin_user() or public.teacher_has_student(student_id));
  end if;
  if not exists(select 1 from pg_policies where schemaname='public' and tablename='attendance' and policyname='teacher_attendance_update_students') then
    create policy teacher_attendance_update_students on public.attendance
      for update to authenticated
      using (public.is_admin_user() or public.teacher_has_student(student_id))
      with check (public.is_admin_user() or public.teacher_has_student(student_id));
  end if;
  if not exists(select 1 from pg_policies where schemaname='public' and tablename='attendance' and policyname='teacher_attendance_delete_students') then
    create policy teacher_attendance_delete_students on public.attendance
      for delete to authenticated
      using (public.is_admin_user() or public.teacher_has_student(student_id));
  end if;
end $$;

-- continuous_assessments: المعلم يكتب فقط لطلابه ومادته
do $$ begin
  if not exists(select 1 from pg_policies where schemaname='public' and tablename='continuous_assessments' and policyname='teacher_continuous_read_write') then
    create policy teacher_continuous_read_write on public.continuous_assessments
      for all to authenticated
      using (public.is_admin_user() or public.teacher_has_student(student_id))
      with check (public.is_admin_user() or (public.teacher_has_student(student_id) and public.teacher_has_class_subject(class_id, subject_id)));
  end if;
end $$;

-- exams: المعلم ينشئ اختبارات لمادته وصفوفه
do $$ begin
  if not exists(select 1 from pg_policies where schemaname='public' and tablename='exams' and policyname='teacher_exams_read_write') then
    create policy teacher_exams_read_write on public.exams
      for all to authenticated
      using (public.is_admin_user() or teacher_id = auth.uid() or public.teacher_has_class_subject(class_id, subject_id))
      with check (public.is_admin_user() or (teacher_id = auth.uid() and public.teacher_has_class_subject(class_id, subject_id)));
  end if;
end $$;

-- exam_scores: المعلم يدخل درجات الاختبارات التي أنشأها أو تخص مادته
do $$ begin
  if not exists(select 1 from pg_policies where schemaname='public' and tablename='exam_scores' and policyname='teacher_exam_scores_read_write') then
    create policy teacher_exam_scores_read_write on public.exam_scores
      for all to authenticated
      using (
        public.is_admin_user()
        or public.teacher_has_student(student_id)
      )
      with check (
        public.is_admin_user()
        or (
          public.teacher_has_student(student_id)
          and exists(select 1 from public.exams e where e.id = exam_id and (e.teacher_id = auth.uid() or public.teacher_has_class_subject(e.class_id, e.subject_id)))
        )
      );
  end if;
end $$;

-- homeworks: المعلم لصفوفه ومواده
do $$ begin
  if not exists(select 1 from pg_policies where schemaname='public' and tablename='homeworks' and policyname='teacher_homeworks_read_write') then
    create policy teacher_homeworks_read_write on public.homeworks
      for all to authenticated
      using (public.is_admin_user() or teacher_id = auth.uid() or public.teacher_has_class_subject(class_id, subject_id))
      with check (public.is_admin_user() or (teacher_id = auth.uid() and public.teacher_has_class_subject(class_id, subject_id)));
  end if;
end $$;

notify pgrst, 'reload schema';
select 'teacher_workflow_policies_ok' as status;



-- ==============================================================================
-- [ARCHIVED MIGRATION]: sql/archive/20_academic_structure_sections_assignments.sql
-- ==============================================================================
-- =============================================================
-- مدارس أمين الرضا (ع) — بنية الشعب والربط الأكاديمي
-- Academic Year → Term → Class → Section → Subject → Session → Teacher → Student
-- Additive migration: لا يحذف بيانات.
-- =============================================================

create extension if not exists pgcrypto;

-- -------------------------------------------------------------
-- 1) الأعوام الدراسية
-- -------------------------------------------------------------
create table if not exists public.academic_years (
  id uuid primary key default gen_random_uuid(),
  name text not null unique,
  start_date date,
  end_date date,
  is_current boolean not null default false,
  created_at timestamptz not null default now()
);

insert into public.academic_years (name, start_date, end_date, is_current)
values ('2026-2027', date '2026-09-01', date '2027-05-31', true)
on conflict (name) do update
set start_date = excluded.start_date,
    end_date = excluded.end_date,
    is_current = true;

-- ربط academic_periods بالعام الدراسي إن أمكن
alter table public.academic_periods add column if not exists academic_year_id uuid null references public.academic_years(id) on delete set null;
alter table public.academic_periods add column if not exists academic_year text not null default '2026-2027';

update public.academic_periods ap
set academic_year_id = ay.id,
    academic_year = ay.name
from public.academic_years ay
where ay.name = '2026-2027'
  and (ap.name like '%2026/2027%' or ap.academic_year = '2026-2027')
  and (ap.academic_year_id is null or ap.academic_year is distinct from ay.name);

-- -------------------------------------------------------------
-- 2) الشعب الدراسية Sections
-- -------------------------------------------------------------
create table if not exists public.sections (
  id uuid primary key default gen_random_uuid(),
  academic_year text not null default '2026-2027',
  class_id uuid not null references public.classes(id) on delete cascade,
  code text not null, -- أ / ب / ج / د
  name text not null,
  capacity int,
  gender_policy text default 'mixed' check (gender_policy in ('mixed','male','female')),
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique(academic_year, class_id, code)
);

-- إنشاء شعب أ، ب، ج، د لكل صف للسنة الحالية إن لم تكن موجودة.
insert into public.sections (academic_year, class_id, code, name)
select '2026-2027', c.id, x.code, c.name || ' — شعبة ' || x.code
from public.classes c
cross join (values ('أ'),('ب'),('ج'),('د')) as x(code)
on conflict (academic_year, class_id, code) do nothing;

-- -------------------------------------------------------------
-- 3) ربط الطلاب بالشعب Enrollments
-- -------------------------------------------------------------
alter table public.students add column if not exists section_id uuid null references public.sections(id) on delete set null;
alter table public.students add column if not exists academic_year text not null default '2026-2027';

create table if not exists public.student_enrollments (
  id uuid primary key default gen_random_uuid(),
  academic_year text not null default '2026-2027',
  student_id uuid not null references public.students(id) on delete cascade,
  class_id uuid not null references public.classes(id) on delete cascade,
  section_id uuid not null references public.sections(id) on delete cascade,
  enrollment_status text not null default 'active' check (enrollment_status in ('active','transferred','withdrawn','graduated','pending')),
  enrollment_date date not null default current_date,
  notes text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique(academic_year, student_id)
);

-- وضع الطلاب الحاليين في شعبة أ افتراضياً حسب صفهم.
update public.students s
set section_id = sec.id,
    academic_year = '2026-2027'
from public.sections sec
where sec.academic_year = '2026-2027'
  and sec.code = 'أ'
  and sec.class_id = s.class_id
  and s.section_id is null
  and s.class_id is not null;

insert into public.student_enrollments (academic_year, student_id, class_id, section_id, enrollment_status)
select '2026-2027', s.id, s.class_id, s.section_id, 'active'
from public.students s
where s.class_id is not null
  and s.section_id is not null
on conflict (academic_year, student_id) do update
set class_id = excluded.class_id,
    section_id = excluded.section_id,
    enrollment_status = 'active',
    updated_at = now();

-- -------------------------------------------------------------
-- 4) إسناد المعلمين Teacher Assignments
-- -------------------------------------------------------------
create table if not exists public.teacher_assignments (
  id uuid primary key default gen_random_uuid(),
  academic_year text not null default '2026-2027',
  academic_period_id uuid null references public.academic_periods(id) on delete set null,
  teacher_id uuid not null references public.users(id) on delete cascade,
  class_id uuid not null references public.classes(id) on delete cascade,
  section_id uuid not null references public.sections(id) on delete cascade,
  subject_id uuid not null references public.subjects(id) on delete cascade,
  weekly_hours numeric default 0,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique(academic_year, academic_period_id, teacher_id, section_id, subject_id)
);

alter table public.weekly_schedule add column if not exists section_id uuid null references public.sections(id) on delete set null;
alter table public.weekly_schedule add column if not exists teacher_assignment_id uuid null references public.teacher_assignments(id) on delete set null;

-- ربط كل حصة حالية بشعبة أ إذا لم تكن محددة.
update public.weekly_schedule ws
set section_id = sec.id
from public.sections sec
where sec.academic_year = '2026-2027'
  and sec.code = 'أ'
  and sec.class_id = ws.class_id
  and ws.section_id is null
  and ws.class_id is not null;

-- توليد إسنادات المعلمين من الجدول الأسبوعي الحالي.
insert into public.teacher_assignments (
  academic_year,
  academic_period_id,
  teacher_id,
  class_id,
  section_id,
  subject_id,
  weekly_hours
)
select
  '2026-2027',
  ws.academic_period_id,
  ws.teacher_id,
  ws.class_id,
  ws.section_id,
  ws.subject_id,
  count(*)::numeric as weekly_hours
from public.weekly_schedule ws
where ws.teacher_id is not null
  and ws.class_id is not null
  and ws.section_id is not null
  and ws.subject_id is not null
group by ws.academic_period_id, ws.teacher_id, ws.class_id, ws.section_id, ws.subject_id
on conflict (academic_year, academic_period_id, teacher_id, section_id, subject_id) do update
set class_id = excluded.class_id,
    weekly_hours = excluded.weekly_hours,
    is_active = true,
    updated_at = now();

-- ربط weekly_schedule بالإسناد المناسب.
update public.weekly_schedule ws
set teacher_assignment_id = ta.id
from public.teacher_assignments ta
where ta.academic_year = '2026-2027'
  and ta.teacher_id = ws.teacher_id
  and ta.section_id = ws.section_id
  and ta.subject_id = ws.subject_id
  and (ta.academic_period_id is not distinct from ws.academic_period_id)
  and ws.teacher_assignment_id is null;

-- -------------------------------------------------------------
-- 5) دوال الصلاحيات بالنطاق Scope Access
-- -------------------------------------------------------------
create or replace function public.current_user_is_admin()
returns boolean
language sql
security definer
set search_path = public
stable
as $$
  select exists(
    select 1 from public.users u
    where u.id = auth.uid()
      and (u.role = 'admin' or coalesce(u.is_super_admin,false)=true)
  );
$$;

create or replace function public.teacher_can_access_section_subject(p_section_id uuid, p_subject_id uuid)
returns boolean
language sql
security definer
set search_path = public
stable
as $$
  select public.current_user_is_admin()
    or exists(
      select 1
      from public.teacher_assignments ta
      where ta.teacher_id = auth.uid()
        and ta.section_id = p_section_id
        and (p_subject_id is null or ta.subject_id = p_subject_id)
        and ta.is_active = true
    );
$$;

create or replace function public.teacher_can_access_student(p_student_id uuid)
returns boolean
language sql
security definer
set search_path = public
stable
as $$
  select public.current_user_is_admin()
    or exists(
      select 1
      from public.student_enrollments se
      join public.teacher_assignments ta
        on ta.section_id = se.section_id
       and ta.academic_year = se.academic_year
       and ta.is_active = true
      where se.student_id = p_student_id
        and se.enrollment_status = 'active'
        and ta.teacher_id = auth.uid()
    );
$$;

grant execute on function public.current_user_is_admin() to authenticated;
grant execute on function public.teacher_can_access_section_subject(uuid,uuid) to authenticated;
grant execute on function public.teacher_can_access_student(uuid) to authenticated;

