-- ==============================================================================
-- =============================================================
-- مدارس أمين الرضا (ع) — فحص التسوية المالية النهائي
-- تقرير فقط: لا يغير أي بيانات.
-- =============================================================

create extension if not exists pgcrypto;

create or replace function public.current_user_is_admin()
returns boolean
language sql
security definer
set search_path = public
