-- في الملف الشخصي وواجهة المعلم/ولي الأمر (المكوّن assets/avatar.js يقرأ
-- العمود avatar_url ويحلّ المسارات عبر /api proxy).
-- شغّل هذا الملف في Supabase → SQL Editor. آمن للتكرار (idempotent).
-- ============================================================================

-- 1) عمود الصورة على users (وولي الأمر/المعلم/الطالب كلهم صفوف في users).
do $$ begin
  if not exists (
    select 1 from information_schema.columns
    where table_schema='public' and table_name='users' and column_name='avatar_url'
  ) then
    alter table public.users add column avatar_url text;
    comment on column public.users.avatar_url
      is 'مسار الصورة داخل حاوية student-photos، أو رابط كامل، أو data: URI';
  end if;
end $$;

-- 2) فهرس خفيف للبحث/التحقق.
create index if not exists idx_users_avatar on public.users (id) where avatar_url is not null;

-- 3) حاوية التخزين (خاصة — القراءة للمصادَقين حسب الصلاحية).
insert into storage.buckets (id, name, public)
values ('student-photos', 'student-photos', false)
on conflict (id) do nothing;

-- 4) سياسات RLS على الكائنات.
do $$ begin
  -- رفع/تعديل صورة المستخدم الخاصة به فقط.
  if not exists(select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='student_photos_owner_write') then
    create policy student_photos_owner_write on storage.objects
      for insert to authenticated
      with check ( bucket_id='student-photos' and (storage.foldername(name))[1] = auth.uid()::text );
  end if;
  if not exists(select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='student_photos_owner_update') then
    create policy student_photos_owner_update on storage.objects
      for update to authenticated
      using ( bucket_id='student-photos' and (storage.foldername(name))[1] = auth.uid()::text )
      with check ( bucket_id='student-photos' and (storage.foldername(name))[1] = auth.uid()::text );
  end if;
  -- قراءة: المعلمون/الإدارة/أولياء الأمور المصرّح لهم.
  if not exists(select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='student_photos_role_read') then
    create policy student_photos_role_read on storage.objects
      for select to authenticated
      using ( bucket_id='student-photos' and exists (
        select 1 from public.users u where u.id = auth.uid()
          and ( u.role in ('admin','academic','academic_admin','teacher','counselor')
                or coalesce(u.is_super_admin,false)=true )
      ));
  end if;
end $$;

-- 5) دالة مساعدة: رفع/تحديث صورة المستخدم (تُستدعى من الواجهة بعد رفع الملف للحاوية).
create or replace function public.set_user_avatar(p_user_id uuid, p_path text)
returns public.users language plpgsql security definer set search_path = public as $$
declare v_role text;
begin
  select role into v_role from public.users where id = p_user_id;
  if v_role is null then raise exception 'المستخدم غير موجود'; end if;
  update public.users set avatar_url = nullif(trim(p_path),'') where id = p_user_id;
  return (select u from public.users u where u.id = p_user_id);
end $$;

grant execute on function public.set_user_avatar(uuid, text) to authenticated;



-- ==============================================================================
-- [ARCHIVED MIGRATION]: sql/archive/111_hash_initial_password.sql
-- ==============================================================================
-- ============================================================================
-- حل خطأ: violates check constraint "registration_families_no_plain_initial_password"
-- المشكلة: وحدة التسجيل ترسل كلمة المرور المؤقتة بنص واضح إلى عمود initial_password،
--          وقيد no_plain_initial_password (موجود في Supabase) يمنع تخزين النص الواضح.
-- الحل: Trigger على مستوى القاعدة يشفّر initial_password تلقائياً (bcrypt) قبل التخزين
--       عبر pgcrypto، دون أي تعديل على واجهة JS ولا مكتبات خارجية.
--       ينطبق على registration_families / registration_students / registration_teachers.
-- ملاحظة أمان: هذا لا يكسر الدخول — auth.users (Supabase Auth) منفصل، وعمود initial_password
--       مجرد سجل؛ كلمة الدخول الفعلية تُدار عبر Supabase Auth.
-- ============================================================================

create extension if not exists pgcrypto;

-- دالة التشفير: تشفّر فقط القيمة النصية غير المشفّرة مسبقاً (تتجاهل القيم الفارغة والهاش).
create or replace function public._hash_initial_password_trg()
returns trigger language plpgsql as $$
begin
  if NEW.initial_password is not null and NEW.initial_password not like '$2%' then
    NEW.initial_password = crypt(NEW.initial_password, gen_salt('bf'));
  end if;
  return NEW;
end $$;

-- تطبيق الـ trigger على الجداول الثلاثة (idempotent — يحذف القديم أولاً).
do $$ begin
  if not exists(select 1 from pg_tables where schemaname='public' and tablename='registration_families') then
    raise notice 'registration_families غير موجود — يتم التخطي';
  else
    drop trigger if exists trg_hash_initial_password on public.registration_families;
    create trigger trg_hash_initial_password
      before insert or update of initial_password on public.registration_families
      for each row execute function public._hash_initial_password_trg();
  end if;

  if not exists(select 1 from pg_tables where schemaname='public' and tablename='registration_students') then
    raise notice 'registration_students غير موجود — يتم التخطي';
  else
    drop trigger if exists trg_hash_initial_password on public.registration_students;
    create trigger trg_hash_initial_password
      before insert or update of initial_password on public.registration_students
      for each row execute function public._hash_initial_password_trg();
  end if;

  if not exists(select 1 from pg_tables where schemaname='public' and tablename='registration_teachers') then
    raise notice 'registration_teachers غير موجود — يتم التخطي';
  else
    drop trigger if exists trg_hash_initial_password on public.registration_teachers;
    create trigger trg_hash_initial_password
      before insert or update of initial_password on public.registration_teachers
      for each row execute function public._hash_initial_password_trg();
  end if;
end $$;

-- تنظيف أي قيم نصية واضعة موجودة مسبقاً (تشفيرها مرة واحدة).
update public.registration_families
  set initial_password = crypt(initial_password, gen_salt('bf'))
  where initial_password is not null and initial_password not like '$2%';
update public.registration_students
  set initial_password = crypt(initial_password, gen_salt('bf'))
  where initial_password is not null and initial_password not like '$2%';
update public.registration_teachers
  set initial_password = crypt(initial_password, gen_salt('bf'))
  where initial_password is not null and initial_password not like '$2%';



-- ==============================================================================
-- [ARCHIVED MIGRATION]: sql/archive/111_personal_landing_health_compat.sql
-- ==============================================================================
-- =============================================================
-- مدارس أمين الرضا (ع) — Hotfix توافق للصفحة الرئيسية والشارات
-- يعالج اختلاف أسماء أعمدة due_date_gregorian / exam_date_gregorian في بعض المخططات.
-- شغّله إذا ظهر خطأ عند تشغيل SQL 109 أو عند فتح portal.html.
-- =============================================================

create extension if not exists pgcrypto;

-- دالة agenda متوافقة لا تشير إلا لأعمدة موجودة في أغلب المخططات.
create or replace function public.get_my_agenda(p_range text default 'today')
returns jsonb
language plpgsql
security definer
set search_path = public
stable
as $$
declare
  uid uuid := auth.uid();
  role_text text;
  from_d date := current_date;
  to_d date := current_date;
  agenda jsonb := '[]'::jsonb;
  st_ids uuid[] := array[]::uuid[];
begin
  select role into role_text from public.users where id=uid;
  if p_range='week' then
    to_d := current_date + 6;
  elsif p_range='tomorrow' then
    from_d := current_date + 1; to_d := current_date + 1;
  elsif p_range='overdue' then
    from_d := current_date - 365; to_d := current_date - 1;
  end if;

  select coalesce(array_agg(id),array[]::uuid[]) into st_ids
  from public.students
  where user_id=uid or parent_id=uid;

  -- واجبات الطالب/ولي الأمر
  if role_text in ('student','parent') and to_regclass('public.homeworks') is not null then
    agenda := agenda || coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',hw.id,'source_table','homeworks','source_id',hw.id,
        'title',hw.title,'agenda_type','assignment','role_scope',role_text,
        'date_gregorian',hw.due_date,
        'priority',case when hw.due_date<current_date then 'high' else 'normal' end,
        'status',case when hw.due_date<current_date then 'overdue' else 'pending' end,
        'action_label','عرض الواجب','action_url','student-homeworks.html','color','#0A6EDC','icon','assignment'
      ))
      from public.homeworks hw
      where hw.due_date between from_d and to_d
        and (
          to_regprocedure('public.student_matches_homework(uuid,uuid)') is null
          or exists(select 1 from unnest(st_ids) as sid(student_id) where public.student_matches_homework(sid.student_id,hw.id))
        )
    ), '[]'::jsonb);
  end if;

  -- واجبات المعلم
  if role_text='teacher' and to_regclass('public.homeworks') is not null then
    agenda := agenda || coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',hw.id,'source_table','homeworks','source_id',hw.id,
        'title','واجب: '||hw.title,'agenda_type','assignment','role_scope','teacher',
        'date_gregorian',hw.due_date,'priority','normal','status','pending',
        'action_label','فتح الواجبات','action_url','teacher.html','color','#0A6EDC','icon','assignment'
      ))
      from public.homeworks hw
      where hw.teacher_id=uid and hw.due_date between from_d and to_d
    ), '[]'::jsonb);
  end if;

  -- الاختبارات الأكاديمية من exams إن وجدت
  if to_regclass('public.exams') is not null then
    agenda := agenda || coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',e.id,'source_table','exams','source_id',e.id,
        'title',e.exam_name,'agenda_type','exam','role_scope','all',
        'date_gregorian',e.exam_date,'priority','high','status','pending',
        'action_label','عرض الاختبارات','action_url','online-exams.html','color','#D32F2F','icon','exam'
      ))
      from public.exams e
      where e.exam_date between from_d and to_d
        and (
          role_text in ('admin','academic','academic_admin','scientific','supervisor')
          or e.teacher_id=uid
          or e.class_id in (select class_id from public.students where id=any(st_ids))
        )
    ), '[]'::jsonb);
  end if;

  -- الاختبارات الإلكترونية من online_exams إن وجدت
  if to_regclass('public.online_exams') is not null then
    agenda := agenda || coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',oe.id,'source_table','online_exams','source_id',oe.id,
        'title',oe.title,'agenda_type','exam','role_scope','all',
        'date_gregorian',coalesce(oe.start_at::date, current_date),
        'priority','high','status','pending',
        'action_label','فتح الاختبار','action_url','online-exams.html','color','#D32F2F','icon','exam'
      ))
      from public.online_exams oe
      where coalesce(oe.start_at::date,current_date) between from_d and to_d
        and (
          role_text in ('admin','academic','academic_admin','scientific','supervisor')
          or oe.teacher_id=uid
          or oe.class_id in (select class_id from public.students where id=any(st_ids))
        )
    ), '[]'::jsonb);
  end if;

  -- الإشعارات
  if to_regclass('public.school_notifications') is not null then
    agenda := agenda || coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',n.id,'source_table','school_notifications','source_id',n.id,
        'title',n.title,'description',n.body,'agenda_type','notification','role_scope','all',
        'date_gregorian',n.created_at::date,'priority','normal',
        'status',case when n.read_at is null then 'pending' else 'done' end,
        'action_label','فتح الإشعارات','action_url','notifications.html','color','#D4AF37','icon','bell'
      ))
      from public.school_notifications n
      where n.recipient_user_id=uid and n.created_at::date between from_d and to_d and n.read_at is null
    ), '[]'::jsonb);
  end if;

  return jsonb_build_object('ok',true,'range',p_range,'items',coalesce(agenda,'[]'::jsonb));
end;
$$;

grant execute on function public.get_my_agenda(text) to authenticated;

notify pgrst, 'reload schema';

select 'personal_landing_health_compat_ready' as status;



